//! Explicit external competitor official CLI ingress; never invoked during validation.
use super::*;
use crate::parity_benchmark::TurnResult;
use std::{ffi::OsString,time::{Duration,Instant},process::Stdio};
pub const HERMES_ROOT:&str="/Users/yang/projects/Hermes_agent";
pub const OPENCLAW_ROOT:&str="/Users/yang/projects/open claw/openclaw";
pub fn minimal_env(home:&Path,key:&str)->BTreeMap<OsString,OsString>{let mut env=BTreeMap::from([(OsString::from("HOME"),home.as_os_str().to_owned()),("PATH".into(),std::env::var_os("PATH").unwrap_or("/usr/bin:/bin".into())),("DASHSCOPE_API_KEY".into(),key.into()),("PYTHON_DOTENV_DISABLED".into(),"1".into())]);for name in ["LANG","LANGUAGE","LC_ALL","SSL_CERT_FILE","SSL_CERT_DIR","TZ"]{if let Some(v)=std::env::var_os(name).filter(|s|!s.is_empty()){env.insert(name.into(),v);}}env}
pub async fn command(program:&str,args:&[String],cwd:&Path,env:Option<&BTreeMap<OsString,OsString>>,seconds:u64)->Result<std::process::Output>{let mut c=tokio::process::Command::new(program);c.args(args).current_dir(cwd).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped()).kill_on_drop(true);if let Some(env)=env{c.env_clear().envs(env);}let output=tokio::time::timeout(Duration::from_secs(seconds),c.output()).await.map_err(|_|"subprocess_timeout")??;Ok(output)}
pub struct HermesAdapter{root:PathBuf,env:BTreeMap<OsString,OsString>,model:String,sessions:BTreeMap<String,Option<String>>,workspaces:BTreeMap<String,PathBuf>}
impl HermesAdapter{pub fn new(root:PathBuf,key:&str,base:&str,model:&str,temperature:f64,max_tokens:u64,thinking:&str)->Result<Self>{let home=root.join("home");private_directory(&home)?;let mut extra=json!({"temperature":temperature,"enable_thinking":thinking!="off"});if thinking=="low"{extra["thinking_budget"]=json!(256)}else if thinking=="medium"{extra["thinking_budget"]=json!(1024)}let config=json!({"_config_version":12,"model":{"provider":"custom:bench","name":model,"max_tokens":max_tokens},"custom_providers":[{"name":"bench","base_url":base,"key_env":"DASHSCOPE_API_KEY","api_mode":"chat_completions","model":model,"context_length":131072,"extra_body":extra}],"agent":{"max_turns":32}});let path=home.join("config.yaml"); // JSON is a YAML subset, preserving the exact semantic configuration.
write_private_json(&path,&config)?;let mut env=minimal_env(&home,key);env.insert("HERMES_HOME".into(),home.into_os_string());Ok(Self{root,env,model:model.into(),sessions:BTreeMap::new(),workspaces:BTreeMap::new()})}
pub async fn start_task(&mut self,id:&str)->Result<()>{let workspace=self.root.join("workspaces").join(id.replace('.',"_"));private_directory(&workspace)?;self.workspaces.insert(id.into(),workspace);self.sessions.insert(id.into(),None);Ok(())}
pub async fn run_turn(&mut self,id:&str,prompt:&str)->Result<TurnResult>{let session=self.sessions.get(id).ok_or("hermes_task_not_started")?.clone();let mut args=vec!["chat".into(),"--query".into(),prompt.into(),"--quiet".into(),"--provider".into(),"custom:bench".into(),"--model".into(),self.model.clone(),"--max-turns".into(),"32".into(),"--ignore-rules".into(),"--source".into(),"benchmark".into()];if let Some(s)=&session{args.extend(["--resume".into(),s.clone()])}let start=Instant::now();let out=command(&format!("{HERMES_ROOT}/venv/bin/hermes"),&args,&self.workspaces[id],Some(&self.env),300).await?;let duration=start.elapsed().as_secs_f64();if !out.status.success(){return Err(format!("hermes_exit:{}",out.status.code().unwrap_or(-1)).into())}let stderr=String::from_utf8(out.stderr)?;let session=match session{Some(s)=>s,None=>{let re=regex::Regex::new(r"(?i)session_id:\s*([A-Za-z0-9_.:-]+)")?;let s=re.captures(&stderr).and_then(|c|c.get(1).map(|m|m.as_str().to_owned())).ok_or("hermes_session_id_missing")?;self.sessions.insert(id.into(),Some(s.clone()));s}};let raw=String::from_utf8(out.stdout)?.trim().to_owned();let prefixes=["⚠ tirith security scanner enabled but not available","⏱ Timeout — denying command"];let diagnostic=|s:&str|prefixes.iter().any(|p|s.trim().starts_with(p));let count=raw.lines().filter(|s|diagnostic(s)).count();let output=raw.lines().filter(|s|!diagnostic(s)).collect::<Vec<_>>().join("\n").trim().to_owned();Ok(TurnResult{text:output,duration_seconds:duration,terminal_status:"process_exit_0".into(),metadata:json!({"session_id_sha256":sha256(session.as_bytes()),"stderr_sha256":sha256(stderr.as_bytes()),"stdout_raw_sha256":sha256(raw.as_bytes()),"cli_diagnostic_count":count})})}}
pub struct OpenClawAdapter{workspace:PathBuf,env:BTreeMap<OsString,OsString>,model:String,thinking:String,sessions:BTreeMap<String,String>}
impl OpenClawAdapter{pub fn new(root:PathBuf,key:&str,base:&str,model:&str,temperature:f64,max_tokens:u64,thinking:&str)->Result<Self>{let(home,state,workspace)=(root.join("home"),root.join("state"),root.join("workspace"));for p in [&home,&state,&workspace]{private_directory(p)?}let config_path=root.join("openclaw.json");let model_ref=format!("dashscope/{model}");let config=json!({"models":{"mode":"merge","providers":{"dashscope":{"baseUrl":base,"apiKey":"${DASHSCOPE_API_KEY}","api":"openai-completions","models":[{"id":model,"name":model,"reasoning":true,"input":["text"],"cost":{"input":0,"output":0,"cacheRead":0,"cacheWrite":0},"contextWindow":131072,"maxTokens":max_tokens}]}}},"agents":{"defaults":{"model":{"primary":model_ref},"models":{model_ref:{"params":{"temperature":temperature,"maxTokens":max_tokens}}},"workspace":workspace},"list":[{"id":"main","default":true}]}});write_private_json(&config_path,&config)?;let mut env=minimal_env(&home,key);env.insert("OPENCLAW_CONFIG_PATH".into(),config_path.into_os_string());env.insert("OPENCLAW_STATE_DIR".into(),state.into_os_string());env.insert("OPENCLAW_LOAD_SHELL_ENV".into(),"0".into());Ok(Self{workspace,env,model:model.into(),thinking:thinking.into(),sessions:BTreeMap::new()})}
pub async fn start_task(&mut self,id:&str)->Result<()>{self.sessions.insert(id.into(),format!("bench-{}",uuid::Uuid::new_v4().simple()));Ok(())}
pub async fn run_turn(&mut self,id:&str,prompt:&str)->Result<TurnResult>{let session=self.sessions.get(id).ok_or("openclaw_task_not_started")?;let args=vec![format!("{OPENCLAW_ROOT}/openclaw.mjs"),"agent".into(),"--local".into(),"--session-id".into(),session.clone(),"--message".into(),prompt.into(),"--thinking".into(),self.thinking.clone(),"--timeout".into(),"300".into(),"--json".into()];let started=Instant::now();let out=command("node",&args,&self.workspace,Some(&self.env),330).await?;let duration=started.elapsed().as_secs_f64();if !out.status.success(){return Err(format!("openclaw_exit:{}",out.status.code().unwrap_or(-1)).into())}let envelope:Value=serde_json::from_slice(&out.stdout).map_err(|_|"openclaw_stdout_not_json")?;let payloads=envelope["payloads"].as_array().filter(|a|!a.is_empty()).ok_or("openclaw_payloads_missing")?;if payloads.iter().any(|v|v.is_object()&&truthy(&v["isError"])){return Err("openclaw_payload_error".into())}let texts:Option<Vec<_>>=payloads.iter().filter(|v|v.is_object()).map(|v|v["text"].as_str()).collect();let texts=texts.filter(|a|!a.is_empty()).ok_or("openclaw_text_missing")?;let meta=&envelope["meta"];let agent=&meta["agentMeta"];if agent["model"]!=self.model{return Err("openclaw_runtime_model_mismatch".into())}if text(&agent["provider"]).is_empty(){return Err("openclaw_runtime_provider_missing".into())}if meta["aborted"]==true||["aborted","error"].contains(&text(&meta["stopReason"])){return Err("openclaw_terminal_failure".into())}Ok(TurnResult{text:texts.join("\n").trim().into(),duration_seconds:duration,terminal_status:meta["stopReason"].as_str().filter(|s|!s.is_empty()).unwrap_or("process_exit_0").into(),metadata:json!({"session_id_sha256":sha256(session.as_bytes()),"stderr_sha256":sha256(&out.stderr),"model":agent["model"],"provider":agent["provider"],"usage":agent["usage"]})})}}
pub async fn version_receipts()->Result<Value>{async fn probe(program:&str,args:&[&str],cwd:&Path)->Result<String>{let out=command(program,&args.iter().map(|s|s.to_string()).collect::<Vec<_>>(),cwd,None,30).await?;if !out.status.success(){return Err(format!("version_probe_exit:{}",out.status.code().unwrap_or(-1)).into())}let bytes=if out.stdout.is_empty(){out.stderr}else{out.stdout};Ok(String::from_utf8(bytes)?.trim().lines().next().ok_or("version_probe_empty")?.into())}let root=repo_root();let diff=command("git",&["diff".into(),"--binary".into()],&root,None,30).await?;if !diff.status.success(){return Err("version_probe_git_diff_failed".into())}Ok(json!({"ai_platform":{"git_commit":probe("git",&["rev-parse","HEAD"],&root).await?,"git_diff_sha256":sha256(&diff.stdout)},"hermes":{"version":probe(&format!("{HERMES_ROOT}/venv/bin/hermes"),&["--version"],Path::new(HERMES_ROOT)).await?,"git_commit":probe("git",&["rev-parse","HEAD"],Path::new(HERMES_ROOT)).await?},"openclaw":{"version":probe("node",&[&format!("{OPENCLAW_ROOT}/openclaw.mjs"),"--version"],Path::new(OPENCLAW_ROOT)).await?,"git_commit":probe("git",&["rev-parse","HEAD"],Path::new(OPENCLAW_ROOT)).await?}}))}
